#!/usr/bin/env python3
"""Exact master -> source frame map (r2 B finding, regenerated by r3 D: the generator was not committed).

The 25 fps master is `ffmpeg -i SRC -r 25 -crf 18 -an` (face_aware_latentsync.make_master). With -r as an OUTPUT option ffmpeg picks
source frames by its own rounding, so master frame m does NOT show source time m/25 (03 / 04 / 05: ~47-73 ms late). This tool builds a
frame-index video with the SOURCE timestamps (frame k carries k as 16 big black/white blocks), sends it through the same ffmpeg call
and reads the index back from every output frame.
    python scripts/quality/master_timing.py --src SRC.mp4 --out <id>_master_timing.json [--master master_25fps.mp4 (frame count check)]
Output: {"j": [source frame index per master frame], "tau_s": [source time of that frame], "nominal_s": m/25, "lag_ms": {...}}
"""
from __future__ import annotations
import argparse, json, pathlib, subprocess, tempfile
import numpy as np

BITS, BW, BH = 16, 24, 24


def main() -> int:
    ap = argparse.ArgumentParser(); ap.add_argument("--src", required=True); ap.add_argument("--out", required=True); ap.add_argument("--master", default=None)
    a = ap.parse_args()
    import av
    c = av.open(a.src); s = c.streams.video[0]; tb = s.time_base; pts = [f.pts for f in c.decode(s)]; c.close()
    tk = np.array(pts, np.float64) * float(tb)
    with tempfile.TemporaryDirectory() as td:
        idx, mst = pathlib.Path(td) / "idx.mkv", pathlib.Path(td) / "m.mp4"
        o = av.open(str(idx), "w"); vs = o.add_stream("ffv1"); vs.width, vs.height, vs.pix_fmt = BW * BITS, BH, "gray"; vs.time_base = tb; vs.codec_context.time_base = tb
        for k, p in enumerate(pts):
            img = np.zeros((BH, BW * BITS), np.uint8)
            for b in range(BITS):
                if (k >> b) & 1: img[:, b * BW:(b + 1) * BW] = 255
            fr = av.VideoFrame.from_ndarray(img, format="gray"); fr.pts = p; fr.time_base = tb
            for pk in vs.encode(fr): o.mux(pk)
        for pk in vs.encode(): o.mux(pk)
        o.close()
        subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-nostdin", "-i", str(idx), "-r", "25", "-crf", "18", "-an", "-pix_fmt", "yuv420p", str(mst)], check=True)
        c = av.open(str(mst)); j = []
        for f in c.decode(c.streams.video[0]):
            g = f.to_ndarray(format="gray").astype(np.float32)
            j.append(sum(1 << b for b in range(BITS) if g[4:BH - 4, b * BW + 4:(b + 1) * BW - 4].mean() > 127))
        c.close()
    j = np.array(j, np.int64)
    if a.master:
        c = av.open(a.master); n = sum(1 for _ in c.decode(c.streams.video[0])); c.close()
        if n != len(j): raise SystemExit(f"index master has {len(j)} frames, real master {n}")
    if (j < 0).any() or (j >= len(tk)).any() or (np.diff(j) < 0).any(): raise SystemExit("decoded frame index out of range / not monotonic")
    tau = tk[j]; nom = np.arange(len(j)) / 25.0; lag = (tau - nom) * 1000
    r = {"src": a.src, "source_frames": len(tk), "master_frames": len(j), "j": j.tolist(), "tau_s": np.round(tau, 6).tolist(), "nominal_s": np.round(nom, 6).tolist(),
         "lag_ms": {"mean": round(float(lag.mean()), 2), "min": round(float(lag.min()), 2), "max": round(float(lag.max()), 2)}}
    pathlib.Path(a.out).write_text(json.dumps(r)); print(json.dumps({k: r[k] for k in ("source_frames", "master_frames", "lag_ms")}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
